//! IANA time zone database.
//!
//! The table is generated by tools/unicode/timezone/generate_data.py from an
//! IANA tzdata release compiled with `zic` for 1970 through 2100. Zones are
//! sorted by ID for binary search; link names share transition ranges with
//! their canonical zone.

const std = @import("std");

const blob = @embedFile("data.bin");

const header_len = 28;
const zone_count = readU16(8);
const abbreviation_count = readU16(10);
const transition_count = readU32(12);
const tzdata_offset = readU32(16);
const tzdata_length = blob[20];
const string_length = readU32(24);

const zone_offset = header_len;
const transition_offset = zone_offset + @as(usize, zone_count) * 12;
const abbreviation_offset = transition_offset + @as(usize, transition_count) * 12;
const strings_offset = abbreviation_offset + @as(usize, abbreviation_count) * 6;

const flag_daylight = 1;

comptime {
    if (blob.len < header_len or !std.mem.eql(u8, blob[0..4], "CJTZ") or
        blob[4] != 1)
    {
        @compileError("invalid time zone data");
    }
    if (strings_offset + @as(usize, string_length) != blob.len) {
        @compileError("invalid time zone data lengths");
    }
}

pub const tzdata_version = blob[strings_offset + @as(usize, tzdata_offset) ..][0..tzdata_length];

pub const names = @import("names.zig");

pub const Offset = struct {
    /// Seconds east of UTC.
    seconds: i32,
    abbreviation: []const u8,
    daylight: bool,
};

pub const Zone = struct {
    id: []const u8,
    first_transition: u32,
    transition_count: u16,
};

fn readU16(offset: usize) u16 {
    return std.mem.readInt(u16, blob[offset..][0..2], .little);
}

fn readU32(offset: usize) u32 {
    return std.mem.readInt(u32, blob[offset..][0..4], .little);
}

fn stringAt(offset: u32, length: u8) []const u8 {
    return blob[strings_offset + @as(usize, offset) ..][0..length];
}

fn zoneAt(index: usize) Zone {
    const base = zone_offset + index * 12;
    return .{
        .id = stringAt(readU32(base), blob[base + 4]),
        .first_transition = readU32(base + 6),
        .transition_count = readU16(base + 10),
    };
}

const Transition = struct {
    at: u32,
    offset: i32,
    abbreviation: []const u8,
    daylight: bool,
};

fn transitionAt(index: usize) Transition {
    const base = transition_offset + index * 12;
    const abbreviation = readU16(base + 8);
    const abbreviation_base = abbreviation_offset + @as(usize, abbreviation) * 6;
    return .{
        .at = readU32(base),
        .offset = @bitCast(readU32(base + 4)),
        .abbreviation = stringAt(
            readU32(abbreviation_base),
            blob[abbreviation_base + 4],
        ),
        .daylight = (blob[base + 10] & flag_daylight) != 0,
    };
}

/// Look up a zone by IANA ID (for example `America/New_York`).
pub fn find(name: []const u8) ?Zone {
    var low: usize = 0;
    var high: usize = zone_count;
    while (low < high) {
        const middle = low + (high - low) / 2;
        const zone = zoneAt(middle);
        switch (std.mem.order(u8, zone.id, name)) {
            .lt => low = middle + 1,
            .gt => high = middle,
            .eq => return zone,
        }
    }
    return null;
}

/// Number of zone IDs (including links).
pub fn count() usize {
    return zone_count;
}

/// Zone ID at `index`, in sorted order.
pub fn at(index: usize) Zone {
    return zoneAt(index);
}

/// Offset in effect for `unix_seconds` (seconds since 1970-01-01 UTC).
///
/// Timestamps before 1970 use the offset in effect at the epoch; timestamps
/// after 2100 use the offset in effect at 2100.
pub fn offsetAt(zone: Zone, unix_seconds: i64) Offset {
    if (zone.transition_count == 0) {
        return .{ .seconds = 0, .abbreviation = "UTC", .daylight = false };
    }
    var low: usize = 0;
    var high: usize = zone.transition_count;
    if (unix_seconds >= @as(i64, std.math.maxInt(u32))) {
        low = high;
    } else if (unix_seconds > 0) {
        const target: u32 = @intCast(unix_seconds);
        while (low < high) {
            const middle = low + (high - low) / 2;
            const transition = transitionAt(zone.first_transition + middle);
            if (transition.at <= target) {
                low = middle + 1;
            } else {
                high = middle;
            }
        }
    }
    const index = if (low == 0) 0 else low - 1;
    const transition = transitionAt(zone.first_transition + index);
    return .{
        .seconds = transition.offset,
        .abbreviation = transition.abbreviation,
        .daylight = transition.daylight,
    };
}

/// Convert a UTC timestamp to the zone's local seconds since the epoch.
pub fn localSeconds(zone: Zone, unix_seconds: i64) i64 {
    return unix_seconds + offsetAt(zone, unix_seconds).seconds;
}

/// Convert local seconds since the epoch in `zone` back to UTC.
pub fn utcSeconds(zone: Zone, local_seconds: i64) i64 {
    const guess = local_seconds - offsetAt(zone, local_seconds).seconds;
    return local_seconds - offsetAt(zone, guess).seconds;
}

test "time zone offsets" {
    const testing = @import("std").testing;
    const new_york = find("America/New_York").?;
    try testing.expectEqualStrings("America/New_York", new_york.id);
    // 2024-01-15T12:00:00Z -> EST, 2024-07-15T12:00:00Z -> EDT.
    const winter = offsetAt(new_york, 1705320000);
    try testing.expectEqual(@as(i32, -5 * 3600), winter.seconds);
    try testing.expectEqualStrings("EST", winter.abbreviation);
    try testing.expect(!winter.daylight);
    const summer = offsetAt(new_york, 1721044800);
    try testing.expectEqual(@as(i32, -4 * 3600), summer.seconds);
    try testing.expectEqualStrings("EDT", summer.abbreviation);
    try testing.expect(summer.daylight);

    const kolkata = find("Asia/Kolkata").?;
    try testing.expectEqual(@as(i32, 5 * 3600 + 1800), offsetAt(kolkata, 0).seconds);

    const lord_howe = find("Australia/Lord_Howe").?;
    const half = offsetAt(lord_howe, 1721044800);
    try testing.expectEqual(@as(i32, 10 * 3600 + 1800), half.seconds);

    try testing.expect(find("UTC") != null);
    try testing.expect(find("Etc/GMT+5") != null);
    try testing.expect(find("Asia/Calcutta") != null);
    try testing.expect(find("Not/AZone") == null);
}

test "time zone local and utc conversion" {
    const testing = @import("std").testing;
    const berlin = find("Europe/Berlin").?;
    const unix: i64 = 1721044800; // 2024-07-15T12:00:00Z
    const local = localSeconds(berlin, unix);
    try testing.expectEqual(unix + 2 * 3600, local);
    try testing.expectEqual(unix, utcSeconds(berlin, local));
}

test "time zone conformance" {
    const testing = @import("std").testing;
    const fixture = @embedFile("conformance.bin");
    try testing.expect(fixture.len >= 12);
    try testing.expectEqualStrings("CJTQ", fixture[0..4]);
    try testing.expectEqual(@as(u8, 1), fixture[4]);
    const version_length = fixture[5];
    const case_count = std.mem.readInt(u32, fixture[8..12], .little);
    try testing.expectEqualStrings(tzdata_version, fixture[12..][0..version_length]);
    var offset: usize = 12 + version_length;
    var failures: usize = 0;
    var total: usize = 0;
    var printed: usize = 0;
    for (0..case_count) |_| {
        const name_length = fixture[offset];
        const daylight = fixture[offset + 1] != 0;
        const unix_seconds = std.mem.readInt(i64, fixture[offset + 4 ..][0..8], .little);
        const expected = std.mem.readInt(i32, fixture[offset + 12 ..][0..4], .little);
        offset += 16;
        const name = fixture[offset .. offset + name_length];
        offset += name_length;
        total += 1;
        const zone = find(name) orelse {
            failures += 1;
            if (printed < 20) {
                printed += 1;
                std.debug.print("timezone mismatch {s}: unknown zone\n", .{name});
            }
            continue;
        };
        const actual = offsetAt(zone, unix_seconds);
        if (actual.seconds != expected or actual.daylight != daylight) {
            failures += 1;
            if (printed < 20) {
                printed += 1;
                std.debug.print(
                    "timezone mismatch {s} {d}: got {d}/{} expected {d}/{}\n",
                    .{ name, unix_seconds, actual.seconds, actual.daylight, expected, daylight },
                );
            }
        }
    }
    std.debug.print("time zone conformance: {d}/{d} passed\n", .{ total - failures, total });
    try testing.expect(failures == 0);
}

test "time zone formatting uses the zone offset" {
    const testing = @import("std").testing;
    const allocator = testing.allocator;
    const dates = @import("../format/dates.zig");
    // 2024-07-15T12:00:00Z is 14:00 in Berlin.
    const date_time = dates.dateTimeFromUnixSecondsInZone(1721044800, "Europe/Berlin");
    try testing.expectEqual(@as(i32, 2024), date_time.year);
    try testing.expectEqual(@as(u8, 7), date_time.month);
    try testing.expectEqual(@as(u8, 15), date_time.day);
    try testing.expectEqual(@as(u8, 14), date_time.hour);
    const text = try dates.formatUnixTimeInZoneAlloc(
        allocator,
        1721044800,
        "en",
        .short,
        "Europe/Berlin",
    );
    defer allocator.free(text);
    try testing.expect(std.mem.indexOf(u8, text, "2:00") != null);
}

/// Whether the zone observes daylight saving time at or after `unix_seconds`.
pub fn usesDaylight(zone: Zone, unix_seconds: i64) bool {
    var index: usize = 0;
    while (index < zone.transition_count) : (index += 1) {
        const transition = transitionAt(zone.first_transition + index);
        if (transition.at >= unix_seconds and transition.daylight) return true;
    }
    return false;
}
